Definition art_secd_fp (sp t parr idx last mb ms : Z) : list (Z * Z) :=
  [ (sp - 96, 96); (0x15c458 + 56, 568); (0x15c6c8 + 16, 16); (parr + 8 * idx, 8); (last + 24, 8); (t + 2800 + 88, 16); (SB + mb / 8, ms / 8); (mb, ms) ].

