Lemma art_cls_dealloc_au : forall c w cl, cl_au (art_cls_dealloc c w cl) = cl_au cl /\ cl_mu (art_cls_dealloc c w cl) = cl_mu cl /\ cl_mfa cl <= cl_mfa (art_cls_dealloc c w cl).
