#[using="Type"] Lemma art_cbr_prim_aruns : forall (Q : list aev -> machine_state -> Prop) (log : list aev) regs (M rom : word -> option byte) (raw : word)
    (sp HI tp key tsd ctx t qs cb spb ris c w d m b1 n sv f1 f2 : Z) (cl : art_cls),
