  art_prim_consts spb ris M -> art_layout M -> art_tsd M tp key tsd ctx t ->
  1 <= c <= 30 -> art_pc_hdr ca true M -> art_cls_rep ca spb ris c cl M -> art_cls_ok c cl -> Z.of_nat (length (cl_cache cl)) <= art_ic_mc c ->
  (art_cls_full c cl = true -> 4 * (Z.of_nat (length (cl_free cl)) + art_ic_mc c / 2) <= 2 ^ 29) ->
  art_cptr_ok sz (cl_au cl) w -> m = ab + d -> 0 <= d -> d + 16 + rs <= sz -> d mod 16 = 0 ->
