  wrA M (SB + (m + 16) / 8) (rs / 8) ->
  cellA M (ca + 2576) 8 sv -> cellA M (t + 2800 + 40) 8 f1 -> cellA M (t + 2800 + 48) 8 f2 ->
  art_evok_list EVOK log (art_cls_events spb c cl) ->
  (forall regs' (M' : word -> option byte),
