  getr regs 12 = Z_to_bv 64 24 -> getr regs 13 = Z_to_bv 64 (art_rel_addr spb e) ->
  HI <= sp - 688 -> sp < 2 ^ 47 -> wrA M (sp - 688) 688 -> 0 <= nt ->
