Lemma art_chunk_apart : forall spb c w c' w', 1 <= c <= 30 -> 1 <= c' <= 30 ->
  0 <= w -> 16 * w + AsanTab.class_size c <= 3758096384 -> (exists i, 16 * w = AsanTab.class_size c * i) ->
  0 <= w' -> 16 * w' + AsanTab.class_size c' <= 3758096384 -> (exists i, 16 * w' = AsanTab.class_size c' * i) ->
