  destruct (Z.eq_dec c c') as [->|NEc]; [|lia].
  assert (NEw : w <> w') by (intros ->; apply NE; reflexivity).
  assert (NEi : i <> i') by (intros ->; apply NEw; lia).
  set (sz := AsanTab.class_size c') in *. rewrite Ei, Ei'. nia.
Qed.

