#[using="Type"] Lemma art_rcy_tail_mem_facts : forall (M : word -> option byte) tmp k b, 0x6b6000 <= tmp -> tmp + 32 < 2 ^ 64 -> cellA M (0x15c6f0 + 152) 4 257 ->
  mem_grows M (art_rcy_tail_mem M tmp k b) /\ art_agree [(tmp, 8); (tmp + 16, 8); (0x15c6f0 + 152, 4)] M (art_rcy_tail_mem M tmp k b)
  /\ cellA (art_rcy_tail_mem M tmp k b) tmp 8 k /\ cellA (art_rcy_tail_mem M tmp k b) (tmp + 16) 8 b /\ cellA (art_rcy_tail_mem M tmp k b) (0x15c6f0 + 152) 4 0.
Proof.
ltac2:(KReplay.run1 (kr_t_NatRecycle5R ()) ["FPX"] (Mh_0138_blobs2.kr_b_146 ())). Qed.

