#[using="Type"] Lemma art_rcy_deq_run : forall (rr pp : list art_qbatch) regs (M rom : word -> option byte) (HI tmp mn GL tf : Z),
  getr regs 2 = Z_to_bv 64 tmp -> getr regs 10 = Z_to_bv 64 0x15c6f0 -> getr regs 11 = Z_to_bv 64 mn ->
