  wrA M tmp 32 -> wrA M (0x15c6f0 + 160) 32 -> Forall (fun b => wrA M (qb_addr b) 8) (pp ++ rr) ->
  cellA M (0x15c6f0 + 184) 8 (art_qbytes rr) -> cellA M (0x15c6f0 + 176) 8 GL -> cellA M (tmp + 24) 8 (art_qbytes pp) -> cellA M (tmp + 8) 8 tf -> (pp <> [] -> tf = art_qhead pp) ->
