Section Recycle.
Variables (HI t ctx tp key tsd spb ris qs parr : Z).
Hypothesis GEO : art_geo HI t ctx tp tsd spb ris qs.
Hypothesis Htp0 : 0x681968 <= tp - 88.
Hypothesis Htsd0 : 0x681968 <= tsd.

#[local] Abbreviation INV := (art_rcy_inv HI t ctx tp key tsd spb ris qs parr).

(* [comment removed for export] *)
Definition art_rcy_W (l : list art_qbatch) : list (Z * Z) := [(HI, 2 ^ 64 - HI); (0x15c6f0 + 152, 40)] ++ map (fun b => (qb_addr b, 8)) l.
(* [comment removed for export] *)
Definition art_rcy_W2 (sp : Z) (l : list art_qbatch) : list (Z * Z) := [(sp - 80, 80); (0x15c6f0 + 152, 40)] ++ map (fun b => (qb_addr b, 8)) l.
Definition art_qin24 (b : art_qbatch) : Prop := spb + 24 * 2 ^ 32 <= qb_addr b /\ qb_addr b + 8192 <= spb + 24 * 2 ^ 32 + 3758096384.

#[using="Type"] Lemma art_rcy_W_gap : forall l a n, Forall art_qin24 l -> a + n <= HI ->
  (a + n <= 0x15c6f0 + 152 \/ 0x15c6f0 + 192 <= a) -> (a + n <= spb + 24 * 2 ^ 32 \/ spb + 24 * 2 ^ 32 + 3758096384 <= a) -> art_gap (art_rcy_W l) a n.
Proof.
ltac2:(KReplay.run1 (kr_t_NarRcy5F ()) ["Recycle"] (Mh_0138_blobs2.kr_b_159 ())). Qed.

#[using="GEO Htp0 Htsd0"] Lemma art_rcy_inv_trq : forall l nt G (M M' : word -> option byte), Forall art_qin24 l -> mem_grows M M' -> art_agree (art_rcy_W l) M M' -> INV nt G M -> INV nt G M'.
Proof.
ltac2:(KReplay.run1 (kr_t_NarRcy5F ()) ["Recycle"] (Mh_0138_blobs2.kr_b_160 ())). Qed.

