#[using="Type"] Lemma art_rcy_head_mem_facts : forall (M : word -> option byte) sp raw regs, 0x6b6000 + 80 <= sp -> sp < 2 ^ 64 ->
  let M1 := art_rcy_head_mem M sp raw regs in
  mem_grows M M1 /\ art_agree [(sp - 80, 80); (0x15c6f0 + 152, 4)] M M1
  /\ cellA M1 (sp - 8) 8 (U raw) /\ cellA M1 (sp - 16) 8 (U (getr regs 8)) /\ cellA M1 (sp - 24) 8 (U (getr regs 9)) /\ cellA M1 (sp - 32) 8 (U (getr regs 18))
  /\ cellA M1 (sp - 40) 8 (U (getr regs 19)) /\ cellA M1 (sp - 48) 8 (U (getr regs 20))
  /\ cellA M1 (sp - 72) 8 0 /\ cellA M1 (sp - 56) 8 0 /\ cellA M1 (0x15c6f0 + 152) 4 257.
Proof.
ltac2:(KReplay.run1 (kr_t_NarRcy5F ()) ["Recycle"] (Mh_0138_blobs2.kr_b_161 ())). Qed.

